/* 192_IngestCaEcosystemProjects.sql — net-new CA projects from the 2026-06-18 ecosystem wave.
   Hand-verified org map + substring-aware dedup vs existing CA MPI. SE only set where NAMED
   (unnamed -> NULL, NOT asserted open). SourceKey ns ca-ecosystem-2026-06:* for traceability. */
SET XACT_ABORT ON; BEGIN TRAN;
DECLARE @now datetimeoffset=sysdatetimeoffset();
DECLARE @p TABLE (SourceKey nvarchar(200),ProjectName nvarchar(500),Stage nvarchar(50),DevName nvarchar(500),DevId bigint,ArchName nvarchar(500),ArchId bigint,SeName nvarchar(500),SeId bigint,Region nvarchar(200),Note nvarchar(max));
MERGE opportunities.MajorProjectsInventory WITH (HOLDLOCK) AS T USING (SELECT * FROM @p) AS S
 ON T.Province=N'CA' AND T.SourceKey=S.SourceKey
WHEN NOT MATCHED THEN INSERT (Province,SourceKey,ProjectName,Stage,ProjectStage,ProponentName,ProponentCanonicalOrgId,ArchitectName,ArchitectCanonicalOrgId,StructuralEngineerName,StructuralEngineerCanonicalOrgId,RegionName,ProjectDescription,FirstSeenAtUtc,LastSeenAtUtc,UpdatedAtUtc)
 VALUES (N'CA',S.SourceKey,S.ProjectName,S.Stage,S.Stage,S.DevName,S.DevId,S.ArchName,S.ArchId,S.SeName,S.SeId,S.Region,S.Note,@now,@now,@now);
COMMIT;
SELECT COUNT(*) AS Ingested, SUM(CASE WHEN ProponentCanonicalOrgId IS NOT NULL OR ArchitectCanonicalOrgId IS NOT NULL THEN 1 ELSE 0 END) AS Linked FROM opportunities.MajorProjectsInventory WHERE Province='CA' AND SourceKey LIKE 'ca-ecosystem-2026-06:%';
